8: export async function runArchiveCommand(workerId,payload,{archiveSupported,saveAndArchive}){
9:   const upstreamReceiptRef=validateArchiveCommand(workerId,payload,{archiveSupported});
10:   // The caller-provided receipt is never sufficient authority to archive.
11:   // Force the canonical flow to re-check terminal external DONE evidence,
12:   // create and verify a fresh correlated durable receipt, then re-check guards.
13:   const result=await saveAndArchive(workerId,{requireDone:true});
