15:   if(!job||job.workerId!==workerId||job.status!=='DONE') return null;
16:   const evidence=(job.evidence||[]).find((item)=>['GITHUB','CORE'].includes(item?.source)&&String(item?.ref||'').trim()&&item?.verifiedAt);
17:   return evidence?{job,evidence}:null;
