20: export async function assertArchiveAllowed(workerId,{getJson,requireDone=true}={}){
21:   if(!ARCHIVE_SUPPORTED_WORKERS.has(workerId)) throw new Error(`ARCHIVE_SELECTOR_UNVERIFIED:${workerId}`);
22:   if(typeof getJson!=='function') throw new Error('ARCHIVE_CONTROLLER_READER_REQUIRED');
23:   const state=await getJson('/api/state');
24:   if(state?.killed) throw new Error('ARCHIVE_CONTROLLER_KILLED');
25:   if(state?.paused) throw new Error('ARCHIVE_OWNER_INTERACTION_READ_ONLY');
26:   const worker=(state?.workers||[]).find((item)=>item.id===workerId);
27:   if(!worker?.enabled) throw new Error(`ARCHIVE_WORKER_DISABLED:${workerId}`);
28:   if(worker.blocked) throw new Error(`ARCHIVE_WORKER_BLOCKED:${workerId}`);
29:   if(worker.lastHeartbeat?.securityBlock) throw new Error(String(worker.lastHeartbeat.securityBlock));
30:   if(worker.lastHeartbeat?.uiBusy!==false) throw new Error('ARCHIVE_UI_NOT_IDLE');
31: 
32:   const autopilot=await getJson('/api/autopilot/state');
33:   if(workerId==='NV02'&&(autopilot?.state?.pendingJobId||autopilot?.state?.uncertainJobId)) throw new Error('ARCHIVE_ACTIVE_JOB_FORBIDDEN');
34:   const previous=autopilot?.snapshot?.previousJob;
35:   if(previous?.workerId===workerId&&ACTIVE_STATUSES.has(previous.status)) throw new Error('ARCHIVE_ACTIVE_JOB_FORBIDDEN');
36:   const proof=doneEvidence(autopilot?.snapshot,workerId);
37:   if(requireDone&&!proof) throw new Error('ARCHIVE_EXTERNAL_DONE_EVIDENCE_REQUIRED');
38:   return proof?{jobId:proof.job.jobId,evidenceRef:proof.evidence.ref}:{jobId:null,evidenceRef:null};
39: }
