62: export async function waitForSaveCompletion(uiState,{sleep=(ms)=>new Promise((resolve)=>setTimeout(resolve,ms)),pollMs=1000,busyObservationPolls=20,maxPolls=120}={}){
63:   let sawBusy=false;
64:   for(let poll=0;poll<maxPolls;poll+=1){
65:     const ui=await uiState();
66:     if(ui?.securityBlock) throw new Error(String(ui.securityBlock));
67:     if(ui?.uiBusy===true) sawBusy=true;
68:     if(sawBusy&&ui?.uiBusy===false) return;
69:     if(!sawBusy&&poll>=busyObservationPolls) throw new Error('SAVE_RESPONSE_NOT_OBSERVED');
70:     await sleep(pollMs);
71:   }
72:   throw new Error('SAVE_RESPONSE_TIMEOUT');
73: }
