75: export async function waitForDurableSaveReceipt(saveToken,workerId,dispatchedAt,{fetchImpl=fetch,sleep=(ms)=>new Promise((resolve)=>setTimeout(resolve,ms)),delays=[0,2000,4000]}={}){
76:   let lastStatus='SAVE_NOT_DURABLE';
77:   for(const delayMs of delays){
78:     if(delayMs) await sleep(delayMs);
79:     const query=new URLSearchParams({token:saveToken,workerId,after:dispatchedAt});
80:     const response=await fetchImpl(`${SAVE_RECEIPT_SERVICE}/api/ui-autopilot/save-receipt?${query.toString()}`,{cache:'no-store'});
81:     if(!response.ok) throw new Error(`SAVE_RECEIPT_HTTP_${response.status}`);
82:     const value=await response.json();
83:     if(value?.ok===true&&value?.status==='DURABLE'&&value?.receiptRef&&value?.checkpointRef&&value?.verifiedAt) return value;
84:     lastStatus=String(value?.status||lastStatus);
85:   }
86:   throw new Error(lastStatus==='DURABLE'?'SAVE_RECEIPT_INCOMPLETE':'SAVE_NOT_DURABLE');
87: }
