import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { execSync } from 'node:child_process';

const repoRoot = 'D:\\TigerIQ\\Workspace\\tigeriq-ai-lab';
const installRoot = 'D:\\TigerIQ\\Apps\\ChromeController';
const localRoot = path.join(installRoot, 'LocalOnly');
const sourceRoot = path.join(localRoot, 'Source');
const releasesRoot = path.join(localRoot, 'Releases');
const runtimeRoot = path.join(installRoot, 'Runtime');
const activeDeployPath = path.join(runtimeRoot, 'active-deploy.json');

console.log('=== Step 1: Copying updated repo files to LocalOnly Source and Current ===');
const filesToSync = [
  {
    src: path.join(repoRoot, 'apps/chrome-controller/direct-cdp-bridge.mjs'),
    dest: path.join(sourceRoot, 'apps/chrome-controller/direct-cdp-bridge.mjs')
  },
  {
    src: path.join(repoRoot, 'apps/chrome-controller/runtime/direct-cdp-archive.mjs'),
    dest: path.join(sourceRoot, 'apps/chrome-controller/runtime/direct-cdp-archive.mjs')
  },
  {
    src: path.join(repoRoot, 'apps/chrome-controller/extension/background.js'),
    dest: path.join(sourceRoot, 'apps/chrome-controller/extension/background.js')
  },
  {
    src: path.join(repoRoot, 'apps/chrome-controller/extension/content.js'),
    dest: path.join(sourceRoot, 'apps/chrome-controller/extension/content.js')
  },
  // Also sync to Current extension folder
  {
    src: path.join(repoRoot, 'apps/chrome-controller/extension/background.js'),
    dest: path.join(installRoot, 'Current/apps/chrome-controller/extension/background.js')
  },
  {
    src: path.join(repoRoot, 'apps/chrome-controller/extension/content.js'),
    dest: path.join(installRoot, 'Current/apps/chrome-controller/extension/content.js')
  }
];

for (const { src, dest } of filesToSync) {
  if (fs.existsSync(src)) {
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    fs.copyFileSync(src, dest);
    console.log(`Synced ${src} -> ${dest}`);
  } else {
    console.warn(`Source not found: ${src}`);
  }
}

console.log('=== Step 2: Computing head and creating Release folder ===');
// Compute local head hash from Source
function getLocalHead(dir) {
  const hash = crypto.createHash('sha256');
  function walk(current) {
    const entries = fs.readdirSync(current, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name));
    for (const e of entries) {
      const full = path.join(current, e.name);
      if (e.name === 'VERSION.txt') continue;
      if (e.isDirectory()) walk(full);
      else if (e.isFile()) {
        const rel = path.relative(dir, full).replace(/\\/g, '/');
        const fileContent = fs.readFileSync(full);
        const fileHash = crypto.createHash('sha256').update(fileContent).digest('hex');
        hash.update(`${rel}|${fileHash}\n`);
      }
    }
  }
  walk(dir);
  return hash.digest('hex').substring(0, 40);
}

const head = getLocalHead(sourceRoot);
const shortHead = head.substring(0, 7);
const timestamp = new Date().toISOString().replace(/[-:]/g, '').replace(/\..+/, 'Z');
const releaseFolderName = `local-${shortHead}-${timestamp}`;
const releaseDir = path.join(releasesRoot, releaseFolderName);

console.log(`Target release dir: ${releaseDir}`);
fs.cpSync(sourceRoot, releaseDir, { recursive: true });
fs.writeFileSync(path.join(releaseDir, 'VERSION.txt'), head + '\r\n', 'utf8');

// Compute bridge hash
const bridgePath = path.join(releaseDir, 'apps/chrome-controller/direct-cdp-bridge.mjs');
const bridgeContent = fs.readFileSync(bridgePath);
const bridgeHash = crypto.createHash('sha256').update(bridgeContent).digest('hex').toLowerCase();

console.log(`Head: ${head}`);
console.log(`Bridge SHA256: ${bridgeHash}`);

console.log('=== Step 3: Updating active-deploy.json ===');
const activeData = {
  schemaVersion: 'tigeriq.appchrome.active-deploy.v1',
  exactHead: head,
  nv02Only: false,
  deploy: releaseDir,
  bridgeSha256: bridgeHash,
  installedAt: new Date().toISOString(),
  installedBootId: 'LOCAL_ONLY',
  activatedAt: new Date().toISOString(),
  activatedBootId: 'LOCAL_ONLY',
  activation: 'LOCAL_ONLY_PUBLISHED',
  sourceMode: 'LOCAL_ONLY',
  gitManaged: false
};

const tmpActive = activeDeployPath + '.tmp';
fs.writeFileSync(tmpActive, JSON.stringify(activeData, null, 4), 'utf8');
fs.renameSync(tmpActive, activeDeployPath);
console.log(`Updated ${activeDeployPath}`);

// Update VERSION.txt in source
fs.writeFileSync(path.join(sourceRoot, 'VERSION.txt'), head + '\r\n', 'utf8');

console.log('=== Step 4: Restarting components via supervisor ===');
// Stop existing listeners on 8798, 8799, 8800 so supervisor immediately restarts with new release
for (const port of [8798, 8799, 8800]) {
  try {
    const out = execSync(`powershell -Command "(Get-NetTCPConnection -LocalPort ${port} -State Listen -ErrorAction SilentlyContinue).OwningProcess"`, { encoding: 'utf8' }).trim();
    const pid = parseInt(out, 10);
    if (pid && pid > 0) {
      console.log(`Stopping stale process on port ${port} (PID: ${pid})`);
      execSync(`powershell -Command "Stop-Process -Id ${pid} -Force -ErrorAction SilentlyContinue"`);
    }
  } catch (err) {
    console.log(`Port ${port} check/stop: ${err.message}`);
  }
}

console.log('Deploy completed successfully.');

