async function test() {
  const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
  const nv02 = targets.find(t => t.url && t.url.includes('/c/'));
  const ws = new WebSocket(nv02.webSocketDebuggerUrl);

  let msgId = 1;
  const send = (method, params) => new Promise(resolve => {
    const id = msgId++;
    const handler = data => {
      const res = JSON.parse(data.data);
      if (res.id === id) {
        ws.removeEventListener('message', handler);
        resolve(res.result);
      }
    };
    ws.addEventListener('message', handler);
    ws.send(JSON.stringify({ id, method, params }));
  });

  ws.onopen = async () => {
    // 1. Get button coords
    const expr = `(()=>{
      const vis = e => { const r = e?.getBoundingClientRect(), s = e && getComputedStyle(e); return !!e && r.width > 0 && r.height > 0 && s.display !== 'none' && s.visibility !== 'hidden'; };
      const btn = [...document.querySelectorAll('button,[role="button"]')].filter(vis).find(e=>{
        const label = (e.getAttribute('aria-label')||e.getAttribute('title')||'').replace(/\\s+/g,' ').trim().toLowerCase();
        return /thao tác với cuộc trò chuyện|conversation actions/i.test(label);
      });
      if (!btn) return null;
      const r = btn.getBoundingClientRect();
      return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
    })()`;
    const res = await send('Runtime.evaluate', { expression: expr, returnByValue: true });
    const point = res?.result?.value;
    console.log('Point:', point);

    if (point) {
      // 2. CDP mouse click
      await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: point.x, y: point.y, button: 'none' });
      await send('Input.dispatchMouseEvent', { type: 'mousePressed', x: point.x, y: point.y, button: 'left', clickCount: 1 });
      await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: point.x, y: point.y, button: 'left', clickCount: 1 });

      await new Promise(r => setTimeout(r, 600));

      // 3. Inspect open menu
      const menuExpr = `(()=>{
        const vis = e => { const r = e?.getBoundingClientRect(), s = e && getComputedStyle(e); return !!e && r.width > 0 && r.height > 0 && s.display !== 'none' && s.visibility !== 'hidden'; };
        const norm = e => (e?.innerText||e?.textContent||e?.getAttribute?.('aria-label')||'').replace(/\\s+/g,' ').trim();
        const items = [...document.querySelectorAll('[role=\"menuitem\"], [role=\"option\"], button')].filter(vis).map(norm).filter(Boolean);
        return items;
      })()`;
      const menuRes = await send('Runtime.evaluate', { expression: menuExpr, returnByValue: true });
      console.log('Menu items after CDP click:', menuRes?.result?.value);
    }
    ws.close();
  };
}
