async function test() {
  const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
  const nv02 = targets.find(t => t.url && t.url.includes('/c/'));
  const ws = new WebSocket(nv02.webSocketDebuggerUrl);

  let msgId = 1;
  const send = (method, params) => new Promise(resolve => {
    const id = msgId++;
    const handler = data => {
      const res = JSON.parse(data.data);
      if (res.id === id) {
        ws.removeEventListener('message', handler);
        resolve(res.result);
      }
    };
    ws.addEventListener('message', handler);
    ws.send(JSON.stringify({ id, method, params }));
  });

  ws.onopen = async () => {
    const expr = `(async ()=>{
      const match = location.pathname.match(/\\/c\\/([^/?#]+)/);
      const conversationId = match?.[1];
      if (!conversationId) return { error: 'NO_CONVERSATION_ID' };

      // Let's get the accessToken from /api/auth/session or window
      let token = null;
      try {
        const sessionRes = await fetch('/api/auth/session');
        const session = await sessionRes.json();
        token = session?.accessToken;
      } catch (e) {
        return { error: 'SESSION_FETCH_FAILED', details: String(e) };
      }

      if (!token) return { error: 'NO_ACCESS_TOKEN' };

      // Try archiving via backend-api
      try {
        const patchRes = await fetch('/backend-api/conversation/' + conversationId, {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + token
          },
          body: JSON.stringify({ is_archived: true })
        });
        const patchData = await patchRes.json().catch(() => ({ status: patchRes.status }));
        return { ok: patchRes.ok, status: patchRes.status, data: patchData };
      } catch (err) {
        return { error: 'PATCH_FAILED', details: String(err) };
      }
    })()`;
    const res = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
    console.log('Archive API Result:', JSON.stringify(res?.result?.value, null, 2));
    ws.close();
  };
}
