import fs from 'node:fs';

// 1. Patch direct-cdp-bridge.mjs
let bridge = fs.readFileSync('apps/chrome-controller/direct-cdp-bridge.mjs', 'utf8');

// Update archiveMenuPointExpr
const menuOld = "['thêm','more','more options','thêm tùy chọn'].includes(label)&&r.top>=0&&r.top<100&&r.right>=innerWidth-120";
const menuNew = "['thêm','more','more options','thêm tùy chọn','thao tác với cuộc trò chuyện','conversation actions','tác vụ khác'].some(k=>label.includes(k))&&r.top>=0&&r.top<100&&r.right>=innerWidth-200";

if (bridge.includes(menuOld)) {
  bridge = bridge.replace(menuOld, menuNew);
  console.log('1. Updated archiveMenuPointExpr in bridge');
} else {
  console.log('1. menuOld not found in bridge');
}

// Update archiveChat to include direct backend API archive check
const archiveOld = "  const p=await pageRpc(target);\n  try{\n    const menuPoint=(await p.call('Runtime.evaluate',{expression:archiveMenuPointExpr(),returnByValue:true,userGesture:true},5000)).result.value;";

const archiveNew = `  const p=await pageRpc(target);
  try{
    const apiArchiveExpr = \`(async ()=>{
      const match = location.pathname.match(/\\\\/c\\\\/([^/?#]+)/);
      const conversationId = match?.[1];
      if (!conversationId) return { ok: false, status: 'ARCHIVE_CONVERSATION_ID_MISSING' };
      try {
        const sessionRes = await fetch('/api/auth/session');
        const session = await sessionRes.json();
        const token = session?.accessToken;
        if (!token) return { ok: false, status: 'ARCHIVE_NO_SESSION_TOKEN' };
        const patchRes = await fetch('/backend-api/conversation/' + conversationId, {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + token
          },
          body: JSON.stringify({ is_archived: true })
        });
        const patchData = await patchRes.json().catch(() => ({ status: patchRes.status }));
        if (patchRes.ok && patchData?.success === true) {
          return { ok: true, status: 'ARCHIVED', conversationId, confirmation: 'API_CONFIRMED' };
        }
      } catch (err) {}
      return { ok: false, status: 'API_ARCHIVE_ATTEMPT_FAILED' };
    })()\`;
    const apiResult = (await p.call('Runtime.evaluate', { expression: apiArchiveExpr, awaitPromise: true, returnByValue: true }, 8000)).result?.value;
    if (apiResult?.ok) {
      log('ARCHIVE_SUCCESS_VIA_API', apiResult);
      return apiResult;
    }
    const menuPoint=(await p.call('Runtime.evaluate',{expression:archiveMenuPointExpr(),returnByValue:true,userGesture:true},5000)).result.value;`;

// Normalize line endings for replacement
let normBridge = bridge.replace(/\r\n/g, '\n');
let normArchiveOld = archiveOld.replace(/\r\n/g, '\n');

if (normBridge.includes(normArchiveOld)) {
  normBridge = normBridge.replace(normArchiveOld, archiveNew);
  console.log('2. Updated archiveChat in bridge with API archive check');
} else {
  console.log('2. archiveOld not found in bridge');
}

fs.writeFileSync('apps/chrome-controller/direct-cdp-bridge.mjs', normBridge, 'utf8');

// 2. Patch content.js
let content = fs.readFileSync('apps/chrome-controller/extension/content.js', 'utf8');
let normContent = content.replace(/\r\n/g, '\n');

const actionOld = "/hành động trong trò chuyện|conversation actions|chat actions/i.test(el.getAttribute('aria-label') || '')";
const actionNew = "/hành động trong trò chuyện|thao tác với cuộc trò chuyện|conversation actions|chat actions/i.test(el.getAttribute('aria-label') || '')";

if (normContent.includes(actionOld)) {
  normContent = normContent.replace(actionOld, actionNew);
  console.log('3. Updated action button regex in content.js');
}

const fallbackOld = "/more|menu|options|thêm|tùy chọn/i.test((el.getAttribute('aria-label') || '') + ' ' + (el.getAttribute('title') || ''))";
const fallbackNew = "/more|menu|options|thêm|tùy chọn|thao tác/i.test((el.getAttribute('aria-label') || '') + ' ' + (el.getAttribute('title') || ''))";

if (normContent.includes(fallbackOld)) {
  normContent = normContent.replace(fallbackOld, fallbackNew);
  console.log('4. Updated fallback button regex in content.js');
}

// Add API archive check to archiveConversation() in content.js
const contentArchiveOld = "  const before = location.href;\n  let menuButton = findCurrentConversationActionButton();";
const contentArchiveNew = `  const before = location.href;
  const conversationId = conversationIdFromPath();
  if (conversationId) {
    try {
      const sessionRes = await fetch('/api/auth/session');
      const session = await sessionRes.json();
      const token = session?.accessToken;
      if (token) {
        const patchRes = await fetch('/backend-api/conversation/' + conversationId, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
          body: JSON.stringify({ is_archived: true })
        });
        const data = await patchRes.json().catch(() => ({}));
        if (patchRes.ok && data?.success === true) {
          return { ok: true, status: 'ARCHIVED', before, after: location.href, method: 'API_CONFIRMED' };
        }
      }
    } catch {}
  }
  let menuButton = findCurrentConversationActionButton();`;

if (normContent.includes(contentArchiveOld)) {
  normContent = normContent.replace(contentArchiveOld, contentArchiveNew);
  console.log('5. Added API archive check to content.js archiveConversation');
}

fs.writeFileSync('apps/chrome-controller/extension/content.js', normContent, 'utf8');
console.log('All patches applied');

