async function main() {
  const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
  const nv02 = targets.find(t => t.type === 'page' && t.url.includes('chatgpt.com'));
  if (!nv02) { console.log('No NV02 tab'); return; }
  const ws = new WebSocket(nv02.webSocketDebuggerUrl);
  let msgId = 1;
  const send = (method, params) => new Promise(resolve => {
    const id = msgId++;
    const h = e => {
      const d = JSON.parse(e.data);
      if (d.id === id) { ws.removeEventListener('message', h); resolve(d.result); }
    };
    ws.addEventListener('message', h);
    ws.send(JSON.stringify({ id, method, params }));
  });
  ws.onopen = async () => {
    const expr = `(()=>{
      const vis = e => { const r = e?.getBoundingClientRect(), s = e && getComputedStyle(e); return !!e && r.width > 0 && r.height > 0 && s.display !== 'none' && s.visibility !== 'hidden'; };
      const btns = [...document.querySelectorAll('button,[role="button"]')].filter(vis).map(e => ({
        tag: e.tagName,
        cls: (e.className || '').toString().slice(0, 80),
        testid: e.getAttribute('data-testid'),
        aria: e.getAttribute('aria-label'),
        title: e.getAttribute('title'),
        effort: e.getAttribute('data-selected-reasoning-effort'),
        haspopup: e.getAttribute('aria-haspopup'),
        text: (e.innerText || e.textContent || '').replace(/\\s+/g, ' ').trim().slice(0, 120),
        r: e.getBoundingClientRect()
      }));
      const alerts = [...document.querySelectorAll('[role="alert"],[role="dialog"],[data-testid*="toast" i]')].map(e => ({
        role: e.getAttribute('role'),
        testid: e.getAttribute('data-testid'),
        text: (e.innerText || e.textContent || '').replace(/\\s+/g, ' ').trim().slice(0, 200)
      }));
      const slug = [...document.querySelectorAll('[data-message-author-role="assistant"][data-message-model-slug]')].at(-1)?.getAttribute('data-message-model-slug');
      return { url: location.href, slug, alerts, btns };
    })()`;
    const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true });
    console.log(JSON.stringify(r?.result?.value, null, 2));
    ws.close();
  };
}
main().catch(console.error);

