async function main() {
  const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
  const nv02 = targets.find(t => t.type === 'page' && t.url.includes('chatgpt.com'));
  if (!nv02) { console.log('No NV02 tab'); return; }
  const ws = new WebSocket(nv02.webSocketDebuggerUrl);
  let msgId = 1;
  const send = (method, params) => new Promise(resolve => {
    const id = msgId++;
    const h = e => {
      const d = JSON.parse(e.data);
      if (d.id === id) { ws.removeEventListener('message', h); resolve(d.result); }
    };
    ws.addEventListener('message', h);
    ws.send(JSON.stringify({ id, method, params }));
  });
  ws.onopen = async () => {
    // 1. Find model button
    const btnExpr = `(()=>{
      const vis = e => { const r = e?.getBoundingClientRect(), s = e && getComputedStyle(e); return !!e && r.width > 0 && r.height > 0 && s.display !== 'none' && s.visibility !== 'hidden'; };
      const btn = [...document.querySelectorAll('button,[role="button"]')].filter(vis).find(e =>
        e.hasAttribute('data-selected-reasoning-effort') || /chọn mô hình chatgpt|choose.*model|model selector/i.test((e.getAttribute('aria-label')||'') + ' ' + (e.getAttribute('title')||''))
      );
      if (!btn) return null;
      const r = btn.getBoundingClientRect();
      return { x: r.left + r.width/2, y: r.top + r.height/2, aria: btn.getAttribute('aria-label'), effort: btn.getAttribute('data-selected-reasoning-effort'), text: (btn.innerText||'').replace(/\\s+/g,' ').trim() };
    })()`;
    const btnRes = await send('Runtime.evaluate', { expression: btnExpr, returnByValue: true });
    const pt = btnRes?.result?.value;
    console.log('Model button:', pt);
    if (!pt) { ws.close(); return; }

    await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: pt.x, y: pt.y, button: 'none' });
    await send('Input.dispatchMouseEvent', { type: 'mousePressed', x: pt.x, y: pt.y, button: 'left', clickCount: 1 });
    await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: pt.x, y: pt.y, button: 'left', clickCount: 1 });
    await new Promise(r => setTimeout(r, 800));

    const menuExpr = `(()=>{
      const vis = e => { const r = e?.getBoundingClientRect(), s = e && getComputedStyle(e); return !!e && r.width > 0 && r.height > 0 && s.display !== 'none' && s.visibility !== 'hidden'; };
      const menus = [...document.querySelectorAll('[role="menu"]')].filter(vis);
      const items = [...document.querySelectorAll('[role="menu"] [role="menuitem"], [role="menu"] [role="menuitemradio"], [role="menu"] [role="option"], [role="menu"] button')].filter(vis).map(e => ({
        tag: e.tagName,
        role: e.getAttribute('role'),
        checked: e.getAttribute('aria-checked'),
        selected: e.getAttribute('aria-selected'),
        testid: e.getAttribute('data-testid'),
        text: (e.innerText || e.textContent || '').replace(/\\s+/g, ' ').trim(),
        r: e.getBoundingClientRect()
      }));
      const sliders = [...document.querySelectorAll('[role="menu"] input, [role="menu"] [role="slider"], [role="slider"], input[type="range"]')].filter(vis).map(e => ({
        tag: e.tagName,
        type: e.getAttribute('type'),
        role: e.getAttribute('role'),
        min: e.getAttribute('min') ?? e.getAttribute('aria-valuemin'),
        max: e.getAttribute('max') ?? e.getAttribute('aria-valuemax'),
        val: e.value ?? e.getAttribute('aria-valuenow'),
        valuetext: e.getAttribute('aria-valuetext'),
        aria: e.getAttribute('aria-label'),
        html: e.outerHTML.slice(0, 300)
      }));
      const menuText = menus.map(m => (m.innerText || '').replace(/\\s+/g, ' ').trim());
      const menuHtml = menus.map(m => m.innerHTML.slice(0, 4000));
      return { menuCount: menus.length, items, sliders, menuText, menuHtml };
    })()`;
    const menuRes = await send('Runtime.evaluate', { expression: menuExpr, returnByValue: true });
    console.log(JSON.stringify(menuRes?.result?.value, null, 2));

    // Dismiss menu
    await send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27, nativeVirtualKeyCode: 27 });
    await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27, nativeVirtualKeyCode: 27 });
    ws.close();
  };
}
main().catch(console.error);

