async function main() {
  const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
  const nv02 = targets.find(t => t.type === 'page' && t.url.includes('chatgpt.com'));
  if (!nv02) { console.log('No NV02 tab'); return; }
  const ws = new WebSocket(nv02.webSocketDebuggerUrl);
  let msgId = 1;
  const send = (method, params) => new Promise(resolve => {
    const id = msgId++;
    const h = e => {
      const d = JSON.parse(e.data);
      if (d.id === id) { ws.removeEventListener('message', h); resolve(d.result); }
    };
    ws.addEventListener('message', h);
    ws.send(JSON.stringify({ id, method, params }));
  });
  ws.onopen = async () => {
    const btnExpr = `(()=>{
      const vis = e => { const r = e?.getBoundingClientRect(), s = e && getComputedStyle(e); return !!e && r.width > 0 && r.height > 0 && s.display !== 'none' && s.visibility !== 'hidden'; };
      const btn = [...document.querySelectorAll('button,[role="button"]')].filter(vis).find(e =>
        e.hasAttribute('data-selected-reasoning-effort') || /chọn mô hình chatgpt|choose.*model|model selector/i.test((e.getAttribute('aria-label')||'') + ' ' + (e.getAttribute('title')||''))
      );
      if (!btn) return null;
      const r = btn.getBoundingClientRect();
      return { x: r.left + r.width/2, y: r.top + r.height/2 };
    })()`;
    const pt = (await send('Runtime.evaluate', { expression: btnExpr, returnByValue: true }))?.result?.value;
    if (!pt) { console.log('No model btn'); ws.close(); process.exit(0); }

    await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: pt.x, y: pt.y, button: 'none' });
    await send('Input.dispatchMouseEvent', { type: 'mousePressed', x: pt.x, y: pt.y, button: 'left', clickCount: 1 });
    await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: pt.x, y: pt.y, button: 'left', clickCount: 1 });
    await new Promise(r => setTimeout(r, 700));

    // Read all menu DOM even if offscreen inside ViewTrack
    const allModelsExpr = `(()=>{
      const menu = document.querySelector('[role="menu"]');
      if (!menu) return { error: 'no menu' };
      const radios = [...menu.querySelectorAll('[role="menuitemradio"], [role="option"], [role="menuitem"]')].map(e => ({
        role: e.getAttribute('role'),
        checked: e.getAttribute('aria-checked'),
        disabled: e.getAttribute('aria-disabled'),
        text: (e.innerText || e.textContent || '').replace(/\\s+/g, ' ').trim()
      }));
      const toggle = menu.querySelector('[data-model-picker-view-toggle="true"]');
      const r = toggle?.getBoundingClientRect();
      return {
        view: menu.querySelector('[data-model-picker-view]')?.getAttribute('data-model-picker-view'),
        radios,
        toggleRect: r ? { x: r.left + r.width/2, y: r.top + r.height/2 } : null
      };
    })()`;
    const initial = (await send('Runtime.evaluate', { expression: allModelsExpr, returnByValue: true }))?.result?.value;
    console.log('Initial:', JSON.stringify(initial, null, 2));

    if (initial?.toggleRect) {
      await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: initial.toggleRect.x, y: initial.toggleRect.y, button: 'none' });
      await send('Input.dispatchMouseEvent', { type: 'mousePressed', x: initial.toggleRect.x, y: initial.toggleRect.y, button: 'left', clickCount: 1 });
      await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: initial.toggleRect.x, y: initial.toggleRect.y, button: 'left', clickCount: 1 });
      await new Promise(r => setTimeout(r, 700));
      const afterToggle = (await send('Runtime.evaluate', { expression: allModelsExpr, returnByValue: true }))?.result?.value;
