async function main() {
  const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
  console.log('All pages on 9222:', targets.filter(t => t.type === 'page').map(t => ({ id: t.id, title: t.title, url: t.url })));
  const nv02 = targets.find(t => t.type === 'page' && t.url.includes('chatgpt.com'));
  if (!nv02) return;
  const ws = new WebSocket(nv02.webSocketDebuggerUrl);
  let msgId = 1;
  const send = (method, params) => new Promise(resolve => {
    const id = msgId++;
    const h = e => { const d = JSON.parse(e.data); if (d.id === id) { ws.removeEventListener('message', h); resolve(d.result); } };
    ws.addEventListener('message', h);
    ws.send(JSON.stringify({ id, method, params }));
  });
  ws.onopen = async () => {
    const expr = `(async ()=>{
      const s = await (await fetch('/api/auth/session')).json().catch(()=>null);
      const token = s?.accessToken;
      const m = await (await fetch('/backend-api/models?history_and_training_disabled=false', { headers: { Authorization: 'Bearer ' + token } })).json();
      return {
        modelSlugsAndTitles: (m.models || []).map(x => x.slug + ' | ' + x.title + ' | max_tokens=' + x.max_tokens + ' | tags=' + (x.tags||[]).join(',')),
        categories: (m.categories || []).map(c => c.category + ' | short=' + c.human_category_short_name + ' | name=' + c.human_category_name + ' | default=' + c.default_model + ' | supported=' + (c.supported_models||[]).join(',') + ' | sub=' + (c.subcategory||''))
      };
    })()`;
    const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
