async function main() {
  for (const port of [9222, 9223]) {
    try {
      const targets = await (await fetch(`http://127.0.0.1:${port}/json`, { signal: AbortSignal.timeout(2000) })).json();
      const tab = targets.find(t => t.type === 'page' && t.url.includes('chatgpt.com'));
      console.log(`=== Port ${port} ===`, tab?.url);
      if (!tab) continue;
      const ws = new WebSocket(tab.webSocketDebuggerUrl);
      await new Promise((res, rej) => {
        ws.onopen = async () => {
          let id = 1;
          const send = (method, params) => new Promise(r => {
            const myId = id++;
            const h = e => { const d = JSON.parse(e.data); if (d.id === myId) { ws.removeEventListener('message', h); r(d.result); } };
            ws.addEventListener('message', h);
            ws.send(JSON.stringify({ id: myId, method, params }));
          });
          const expr = `(async ()=>{
            const s = await (await fetch('/api/auth/session')).json().catch(()=>null);
            const token = s?.accessToken;
            if (!token) return { error: 'no token', user: s?.user?.email };
            const m = await (await fetch('/backend-api/models', { headers: { Authorization: 'Bearer ' + token } })).json().catch(e => ({ err: String(e) }));
            const btns = [...document.querySelectorAll('button[aria-label="Chọn mô hình ChatGPT"], button[data-selected-reasoning-effort]')].map(b => ({
              text: (b.innerText||'').replace(/\\s+/g,' ').trim(),
              effort: b.getAttribute('data-selected-reasoning-effort')
            }));
            return {
              email: s?.user?.email,
              btns,
              models61: (m?.models || []).filter(x => /6\.1|sol|gpt-6/i.test(x.slug + ' ' + x.title)).map(x => ({ slug: x.slug, title: x.title, enabled_tools: x.enabled_tools?.length, product_features: x.product_features, tags: x.tags }))
            };
          })()`;
          const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
          console.log(JSON.stringify(r?.result?.value, null, 2));
          ws.close();
          res();
        };
        ws.onerror = rej;
      });
    } catch (e) {
      console.log(`Port ${port} error:`, e.message);
    }
  }
  process.exit(0);
}
