async function main() {
  const created = await (await fetch('http://127.0.0.1:9222/json/new?https://chatgpt.com/', { method: 'PUT' })).json();
  const ws = new WebSocket(created.webSocketDebuggerUrl);
  let msgId = 1;
  const send = (method, params) => new Promise(resolve => {
    const id = msgId++;
    const h = e => { const d = JSON.parse(e.data); if (d.id === id) { ws.removeEventListener('message', h); resolve(d.result); } };
    ws.addEventListener('message', h);
    ws.send(JSON.stringify({ id, method, params }));
  });

  ws.onopen = async () => {
    let pt = null;
    for (let i = 0; i < 20; i++) {
      await new Promise(r => setTimeout(r, 1000));
      pt = (await send('Runtime.evaluate', { expression: `(()=>{
        const vis = e => { const r = e?.getBoundingClientRect(), s = e && getComputedStyle(e); return !!e && r.width > 0 && r.height > 0 && s.display !== 'none' && s.visibility !== 'hidden'; };
        const modelBtn = [...document.querySelectorAll('button,[role="button"]')].filter(vis).find(e => e.hasAttribute('data-selected-reasoning-effort') || /chọn mô hình chatgpt/i.test(e.getAttribute('aria-label')||''));
        if (!modelBtn) return null;
        const r = modelBtn.getBoundingClientRect();
        return { x: r.left + r.width/2, y: r.top + r.height/2, text: (modelBtn.innerText||'').replace(/\\s+/g,' ').trim(), effort: modelBtn.getAttribute('data-selected-reasoning-effort') };
      })()`, returnByValue: true }))?.result?.value;
      if (pt) break;
    }
    console.log('Root chat model btn:', pt);

    // Check rate limits / entitlement / accounts/check
    const meta = (await send('Runtime.evaluate', { expression: `(async ()=>{
      const s = await (await fetch('/api/auth/session')).json().catch(()=>null);
      const token = s?.accessToken;
      const headers = { Authorization: 'Bearer ' + token };
      const acc = await (await fetch('/backend-api/accounts/check/v4-2023-04-27', { headers })).json().catch(e=>({err:String(e)}));
      const m = await (await fetch('/backend-api/models', { headers })).json().catch(e=>({err:String(e)}));
      return {
        plan: acc?.accounts?.default?.entitlement,
        rate_limits: m?.rate_limits,
        model_groups: Object.keys(m || {}),
        default_category: m?.default_category,
        models_61: (m?.models || []).filter(x => x.slug.includes('6'))
      };
    })()`, awaitPromise: true, returnByValue: true }))?.result?.value;
    console.log('Meta:', JSON.stringify(meta, null, 2));

    if (pt) {
      await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: pt.x, y: pt.y, button: 'none' });
      await send('Input.dispatchMouseEvent', { type: 'mousePressed', x: pt.x, y: pt.y, button: 'left', clickCount: 1 });
      await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: pt.x, y: pt.y, button: 'left', clickCount: 1 });
      await new Promise(r => setTimeout(r, 800));

      const togglePt = (await send('Runtime.evaluate', { expression: `(()=>{ const t = document.querySelector('[role="menu"] [data-model-picker-view-toggle="true"]'); if(!t) return null; const r=t.getBoundingClientRect(); return { x:r.left+r.width/2, y:r.top+r.height/2 }; })()`, returnByValue: true }))?.result?.value;
      if (togglePt) {
        await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: togglePt.x, y: togglePt.y, button: 'none' });
        await send('Input.dispatchMouseEvent', { type: 'mousePressed', x: togglePt.x, y: togglePt.y, button: 'left', clickCount: 1 });
        await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: togglePt.x, y: togglePt.y, button: 'left', clickCount: 1 });
        await new Promise(r => setTimeout(r, 700));
      }

      const menuDump = (await send('Runtime.evaluate', { expression: `(()=>{
        const m = document.querySelector('[role="menu"]');
        return m ? { innerText: m.innerText, html: m.innerHTML.replace(/<svg[\\s\\S]*?<\\/svg>/g, '') } : null;
      })()`, returnByValue: true }))?.result?.value;
      console.log('Root chat menuDump:', JSON.stringify(menuDump, null, 2));
    }

    await fetch(`http://127.0.0.1:9222/json/close/${created.id}`).catch(()=>{});
    ws.close();
    setTimeout(() => process.exit(0), 300);
  };
}
main().catch(e => { console.error(e); setTimeout(() => process.exit(1), 200); });

async function main() {
  const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
  const nv02 = targets.find(t => t.type === 'page' && t.url.includes('chatgpt.com'));
  if (!nv02) return;
  const ws = new WebSocket(nv02.webSocketDebuggerUrl);
  let msgId = 1;
  const send = (method, params) => new Promise(resolve => {
    const id = msgId++;
    const h = e => { const d = JSON.parse(e.data); if (d.id === id) { ws.removeEventListener('message', h); resolve(d.result); } };
    ws.addEventListener('message', h);
    ws.send(JSON.stringify({ id, method, params }));
  });
  ws.onopen = async () => {
    const r = (await send('Runtime.evaluate', { expression: `(async ()=>{
      const s = await (await fetch('/api/auth/session')).json();
      const headers = { Authorization: 'Bearer ' + s.accessToken };
      const acc = await (await fetch('/backend-api/accounts/check/v4-2023-04-27', { headers })).json();
      const m = await (await fetch('/backend-api/models', { headers })).json();
      return {
        account_ordering: acc?.account_ordering,
        accounts: Object.entries(acc?.accounts || {}).map(([k, v]) => ({ id: k, name: v?.account?.name, structure: v?.account?.structure, plan: v?.entitlement?.subscription_plan })),
        model_picker_version: m?.model_picker_version,
        default_model_slug: m?.default_model_slug,
        versions: m?.versions,
        non_wm_models: (m?.models || []).filter(x => !x.is_work_mode_model).map(x => ({ slug: x.slug, title: x.title, tags: x.tags })),
        wm_models: (m?.models || []).filter(x => x.is_work_mode_model).map(x => ({ slug: x.slug, title: x.title })),
        categories: (m?.categories || []).map(c => ({ cat: c.category, short: c.human_category_short_name, def: c.default_model, ver: c.model_version }))
      };
    })()`, awaitPromise: true, returnByValue: true }))?.result?.value;
    console.log(JSON.stringify(r, null, 2));
    ws.close();
    setTimeout(() => process.exit(0), 200);
  };
}
main().catch(e => { console.error(e); process.exit(1); });

