async function checkPort(port) {
  const targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json();
  const tab = targets.find(t => t.type === 'page' && t.url.includes('chatgpt.com'));
  if (!tab) return { port, error: 'no chatgpt tab' };
  const ws = new WebSocket(tab.webSocketDebuggerUrl);
  let msgId = 1;
  const send = (method, params) => new Promise(resolve => {
    const id = msgId++;
    const h = e => { const d = JSON.parse(e.data); if (d.id === id) { ws.removeEventListener('message', h); resolve(d.result); } };
    ws.addEventListener('message', h);
    ws.send(JSON.stringify({ id, method, params }));
  });
  return await new Promise(resolve => {
    ws.onopen = async () => {
      const r = (await send('Runtime.evaluate', { expression: `(async ()=>{
        const s = await (await fetch('/api/auth/session')).json().catch(()=>null);
        const headers = s?.accessToken ? { Authorization: 'Bearer ' + s.accessToken } : {};
        const m = s?.accessToken ? await (await fetch('/backend-api/models', { headers })).json().catch(()=>null) : null;
        const btns = [...document.querySelectorAll('button[aria-label="Chọn mô hình ChatGPT"], button[data-selected-reasoning-effort]')].map(b => ({
          aria: b.getAttribute('aria-label'),
          effort: b.getAttribute('data-selected-reasoning-effort'),
          text: (b.innerText||'').replace(/\\s+/g,' ').trim()
        }));
        return {
          port: ${port},
          email: s?.user?.email,
          btns,
          versions: m?.versions?.map(v => ({ id: v.id, display: v.display_text, intel: v.display_text_for_intelligence, presets: v.intelligence_presets?.map(p => ({ id: p.id, title: p.title, slug: p.model_slug })) })),
          default_model_slug: m?.default_model_slug
        };
      })()`, awaitPromise: true, returnByValue: true }))?.result?.value;
      ws.close();
      resolve(r);
    };
  });
}

Promise.all([checkPort(9222), checkPort(9223)]).then(res => {
  console.log(JSON.stringify(res, null, 2));
  setTimeout(() => process.exit(0), 200);
}).catch(e => { console.error(e); process.exit(1); });

