async function main() {
  const created = await (await fetch('http://127.0.0.1:9222/json/new?https://chatgpt.com/', { method: 'PUT' })).json();
  const ws = new WebSocket(created.webSocketDebuggerUrl);
  let msgId = 1;
  const send = (method, params) => new Promise(resolve => {
    const id = msgId++;
    const h = e => { const d = JSON.parse(e.data); if (d.id === id) { ws.removeEventListener('message', h); resolve(d.result); } };
    ws.addEventListener('message', h);
    ws.send(JSON.stringify({ id, method, params }));
  });

  ws.onopen = async () => {
    let pt = null;
    for (let i = 0; i < 20; i++) {
      await new Promise(r => setTimeout(r, 1000));
      pt = (await send('Runtime.evaluate', { expression: `(()=>{
        const vis = e => { const r = e?.getBoundingClientRect(), s = e && getComputedStyle(e); return !!e && r.width > 0 && r.height > 0 && s.display !== 'none' && s.visibility !== 'hidden'; };
        const modelBtn = [...document.querySelectorAll('button,[role="button"]')].filter(vis).find(e => e.hasAttribute('data-selected-reasoning-effort') || /chọn mô hình chatgpt/i.test(e.getAttribute('aria-label')||''));
        if (!modelBtn) return null;
        const r = modelBtn.getBoundingClientRect();
        return { x: r.left + r.width/2, y: r.top + r.height/2, text: (modelBtn.innerText||'').replace(/\\s+/g,' ').trim(), effort: modelBtn.getAttribute('data-selected-reasoning-effort') };
      })()`, returnByValue: true }))?.result?.value;
      if (pt) break;
    }
    console.log('Before:', pt);

    // Open menu
    await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: pt.x, y: pt.y, button: 'none' });
    await send('Input.dispatchMouseEvent', { type: 'mousePressed', x: pt.x, y: pt.y, button: 'left', clickCount: 1 });
    await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: pt.x, y: pt.y, button: 'left', clickCount: 1 });
    await new Promise(r => setTimeout(r, 700));

    // Move slider left twice
    await send('Runtime.evaluate', { expression: `document.querySelector('[data-reasoning-slider="true"]')?.focus()`, returnByValue: true });
    for (let k = 0; k < 2; k++) {
      await send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'ArrowLeft', code: 'ArrowLeft', windowsVirtualKeyCode: 37, nativeVirtualKeyCode: 37 });
      await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'ArrowLeft', code: 'ArrowLeft', windowsVirtualKeyCode: 37, nativeVirtualKeyCode: 37 });
      await new Promise(r => setTimeout(r, 250));
    }

    const slider0 = (await send('Runtime.evaluate', { expression: `(()=>{
      const b = document.querySelector('button[aria-label="Chọn mô hình ChatGPT"]');
      const thumb = document.querySelector('[data-reasoning-slider="true"] [role="slider"]');
      const status = document.querySelector('[role="menu"] [role="status"]')?.innerText;
      const toggle = document.querySelector('[role="menu"] [data-model-picker-view-toggle="true"]')?.innerText;
      return { btnText: b?.innerText?.replace(/\\s+/g,' ')?.trim(), btnEffort: b?.getAttribute('data-selected-reasoning-effort'), thumbVal: thumb?.getAttribute('aria-valuenow'), status, toggle };
    })()`, returnByValue: true }))?.result?.value;
    console.log('After ArrowLeft x2:', slider0);

    await fetch(`http://127.0.0.1:9222/json/close/${created.id}`).catch(()=>{});
    ws.close();
    setTimeout(() => process.exit(0), 200);
  };
}
main().catch(e => { console.error(e); process.exit(1); });

