      const p = document.querySelector('[role="menu"] [data-reasoning-slider="true"]');
      const t = p?.querySelector('[role="slider"]');
      const s = document.querySelector('[role="menu"] [role="status"]')?.innerText;
      const tog = document.querySelector('[role="menu"] [data-model-picker-view-toggle="true"]')?.innerText?.replace(/\\s+/g,' ')?.trim();
      const b = document.querySelector('button[aria-label="Chọn mô hình ChatGPT"], button[data-selected-reasoning-effort]');
      return { val: t?.getAttribute('aria-valuenow'), status: s, tog, btnText: b?.innerText?.replace(/\\s+/g,' ')?.trim(), btnEffort: b?.getAttribute('data-selected-reasoning-effort') };
    })()`, returnByValue: true }))?.result?.value;
    console.log('6. Final GPT-6 + slider=0:', afterLow);

    await send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27, nativeVirtualKeyCode: 27 });
    await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27, nativeVirtualKeyCode: 27 });

    await fetch(`http://127.0.0.1:9222/json/close/${created.id}`).catch(()=>{});
    ws.close();
    setTimeout(() => process.exit(0), 200);
  };
}
main().catch(e => { console.error(e); setTimeout(() => process.exit(1), 200); });

