async function main() {
  const created = await (await fetch('http://127.0.0.1:9222/json/new?https://chatgpt.com/', { method: 'PUT' })).json();
  const ws = new WebSocket(created.webSocketDebuggerUrl);
  let msgId = 1;
  const send = (method, params) => new Promise(resolve => {
    const id = msgId++;
    const h = e => { const d = JSON.parse(e.data); if (d.id === id) { ws.removeEventListener('message', h); resolve(d.result); } };
    ws.addEventListener('message', h);
    ws.send(JSON.stringify({ id, method, params }));
  });

  ws.onopen = async () => {
    const getBtn = async () => (await send('Runtime.evaluate', { expression: `(()=>{
      const vis = e => { const r = e?.getBoundingClientRect(), s = e && getComputedStyle(e); return !!e && r.width > 0 && r.height > 0 && s.display !== 'none' && s.visibility !== 'hidden'; };
      const b = [...document.querySelectorAll('button,[role="button"]')].filter(vis).find(e => e.hasAttribute('data-selected-reasoning-effort') || /chọn mô hình chatgpt/i.test(e.getAttribute('aria-label')||''));
      if (!b) return null;
      const r = b.getBoundingClientRect();
      return { x: r.left + r.width/2, y: r.top + r.height/2, text: (b.innerText||'').replace(/\\s+/g,' ').trim(), effort: b.getAttribute('data-selected-reasoning-effort') };
    })()`, returnByValue: true }))?.result?.value;

    let pt = null;
    for (let i = 0; i < 20; i++) {
      await new Promise(r => setTimeout(r, 1000));
      pt = await getBtn();
      if (pt) { await new Promise(r => setTimeout(r, 1500)); pt = await getBtn(); break; }
    }
    console.log('1. Root settled pill:', pt);

    await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: pt.x, y: pt.y, button: 'none' });
    await send('Input.dispatchMouseEvent', { type: 'mousePressed', x: pt.x, y: pt.y, button: 'left', clickCount: 1 });
    await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: pt.x, y: pt.y, button: 'left', clickCount: 1 });
    await new Promise(r => setTimeout(r, 700));

    const before = (await send('Runtime.evaluate', { expression: `(()=>{
      const p = document.querySelector('[role="menu"] [data-reasoning-slider="true"]');
      const t = p?.querySelector('[role="slider"]');
      const s = document.querySelector('[role="menu"] [role="status"]')?.innerText;
      const radios = [...document.querySelectorAll('[role="menu"] [role="menuitemradio"]')].map(e => ({ text: e.innerText.trim(), checked: e.getAttribute('aria-checked') }));
      return { val: t?.getAttribute('aria-valuenow'), status: s, radios };
    })()`, returnByValue: true }))?.result?.value;
    console.log('2. Menu before ArrowLeft:', before);

    await send('Runtime.evaluate', { expression: `document.querySelector('[role="menu"] [data-reasoning-slider="true"]')?.focus()`, returnByValue: true });
    for (let k = 0; k < 2; k++) {
      await send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'ArrowLeft', code: 'ArrowLeft', windowsVirtualKeyCode: 37, nativeVirtualKeyCode: 37 });
      await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'ArrowLeft', code: 'ArrowLeft', windowsVirtualKeyCode: 37, nativeVirtualKeyCode: 37 });
      await new Promise(r => setTimeout(r, 250));
    }

    const after0 = (await send('Runtime.evaluate', { expression: `(()=>{
      const p = document.querySelector('[role="menu"] [data-reasoning-slider="true"]');
      const t = p?.querySelector('[role="slider"]');
      const s = document.querySelector('[role="menu"] [role="status"]')?.innerText;
      const tog = document.querySelector('[role="menu"] [data-model-picker-view-toggle="true"]')?.innerText?.replace(/\\s+/g,' ')?.trim();
      const b = document.querySelector('button[aria-label="Chọn mô hình ChatGPT"], button[data-selected-reasoning-effort]');
      return { val: t?.getAttribute('aria-valuenow'), status: s, tog, btnText: b?.innerText?.replace(/\\s+/g,' ')?.trim(), btnEffort: b?.getAttribute('data-selected-reasoning-effort') };
    })()`, returnByValue: true }))?.result?.value;
    console.log('3. Menu & pill at slider=0:', after0);

    // Also restore slider back to 2 in root tab if needed? No, leave at 0 or check!
    await send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27, nativeVirtualKeyCode: 27 });
    await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27, nativeVirtualKeyCode: 27 });

    await fetch(`http://127.0.0.1:9222/json/close/${created.id}`).catch(()=>{});
    ws.close();
    setTimeout(() => process.exit(0), 200);
  };
}
main().catch(e => { console.error(e); setTimeout(() => process.exit(1), 200); });

