package ai.tigeriq.camera

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

class ReversePathGeometryTest {

    @Test
    fun sampleTrackPoint_clampsBoundsWithoutThrowingForInnerTireOffsets() {
        val inner = ReversePathGeometry.sampleTrackPoint(
            distanceBack = 1.5,
            roadWheelDegrees = -32.0,
            wheelbaseMeters = 2.9,
            lateralOffsetMeters = -0.56
        )
        val outer = ReversePathGeometry.sampleTrackPoint(
            distanceBack = 1.5,
            roadWheelDegrees = -32.0,
            wheelbaseMeters = 2.9,
            lateralOffsetMeters = -0.92
        )
        assertTrue(outer.x < inner.x)
        assertTrue(inner.back > 0.0)

        // Edge clamp safety: out-of-range inputs should never crash the overlay
        val extreme = ReversePathGeometry.sampleTrackPoint(
            distanceBack = 10.0,
            roadWheelDegrees = -75.0,
            wheelbaseMeters = 0.5,
            lateralOffsetMeters = 5.0
        )
        assertTrue(extreme.x.isFinite() && extreme.back.isFinite())
    }

    @Test
    fun oemWheelTrack_preservesGapAndNonCrossingBandsAcrossAngles() {
        val angles = listOf(-32.0, -18.0, 0.0, 18.0, 32.0)
        val distances = listOf(0.45, 1.0, 1.8, 2.8)
        for (angle in angles) {
            for (s in distances) {
                val pLeftOuter = projectPoint(s, -0.92, angle)
                val pLeftTireOuter = projectPoint(s, -0.84, angle)
                val pLeftTireInner = projectPoint(s, -0.56, angle)
                val pRightTireInner = projectPoint(s, 0.56, angle)
                val pRightTireOuter = projectPoint(s, 0.84, angle)
                val pRightOuter = projectPoint(s, 0.92, angle)

                // Screen X ordering must stay strictly separated from left outer to right outer
                assertTrue("Gap between left outer rail and tire broken at angle=$angle s=$s", pLeftOuter.x < pLeftTireOuter.x - 1f)
                assertTrue("Left tire ribbon collapsed at angle=$angle s=$s", pLeftTireOuter.x < pLeftTireInner.x - 2f)
                assertTrue("Left and right tire tracks crossed at angle=$angle s=$s", pLeftTireInner.x < pRightTireInner.x - 10f)
                assertTrue("Right tire ribbon collapsed at angle=$angle s=$s", pRightTireInner.x < pRightTireOuter.x - 2f)
                assertTrue("Gap between right tire and outer rail broken at angle=$angle s=$s", pRightTireOuter.x < pRightOuter.x - 1f)
            }
        }
    }

    @Test
    fun redBumperBar_staysFixedAtRearBumperWhenSteering() {
        val straightLeft = projectPoint(0.50, -0.92, 0.0)
        val straightRight = projectPoint(0.50, 0.92, 0.0)
        assertEquals(0f, (straightLeft.x + straightRight.x) * 0.5f - 540f, 0.5f)
        assertEquals(straightLeft.y, straightRight.y, 0.5f)
    }

    private fun projectPoint(sMeters: Double, lateralMeters: Double, wheelDeg: Double): ReversePathGeometry.ScreenPoint {
        val pt = ReversePathGeometry.sampleTrackPoint(sMeters, wheelDeg, 2.9, lateralMeters)
        return ReversePathGeometry.worldToScreen(
            worldX = pt.x,
            worldBack = pt.back,
            cx = 540f,
            bottomY = 860f,
            topY = 380f,
            bottomHalfW = 324f,
            topHalfW = 140f
        )
    }
}

package ai.tigeriq.camera

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import kotlin.math.abs

class MotionSteeringEstimatorTest {

    @Test
    fun stationaryMemsBiasDrift_adaptsOutToZero() {
        val estimator = MotionSteeringEstimator()
        var t = 1000L
        for (i in 0..80) {
            estimator.onGyroSample(0f, 0.016f, 0f, 0f, 9.81f, 0f, true, t)
            val deg = estimator.step(t, inverted = false)
            assertEquals("Tiny constant bias must not bend guidelines", 0f, deg, 0.01f)
            t += 30L
        }
    }

    @Test
    fun idleEngineVibration_andMountShake_areRejectedToZero() {
        val estimator = MotionSteeringEstimator()
        var t = 1000L
        // Alternating +/- high vibration while camera image is static
        for (i in 0..50) {
            val spike = if (i % 2 == 0) 0.22f else -0.22f
            estimator.onVideoMotionScore(0.3f, t)
            estimator.onGyroSample(0f, spike, 0f, 0f, 9.81f, 0f, true, t)
            val deg = estimator.step(t, inverted = false)
            assertTrue("Alternating vibration caused false curve: $deg", abs(deg) < 0.5f)
            t += 25L
        }
    }

    @Test
    fun pedestrianCrossingBehindParkedCar_withoutGyro_keepsLinesStraight() {
        val estimator = MotionSteeringEstimator()
        var t = 2000L
        for (i in 0..30) {
            estimator.onVideoMotionScore(18.0f, t)
            estimator.onGyroSample(0f, 0.002f, 0f, 0f, 9.81f, 0f, true, t)
            val deg = estimator.step(t, inverted = false)
            assertEquals(0f, deg, 0.01f)
            t += 30L
        }
    }

    @Test
    fun briefTapBumpOnStaticScene_isRejected() {
        val estimator = MotionSteeringEstimator()
        var t = 3000L
        estimator.onVideoMotionScore(0.2f, t)
        estimator.onGyroSample(0f, -0.14f, 0f, 0f, 9.81f, 0f, true, t)
        assertEquals(0f, estimator.step(t, inverted = false), 0.01f)
        t += 40L
        estimator.onGyroSample(0f, 0.0f, 0f, 0f, 9.81f, 0f, true, t)
        assertEquals(0f, estimator.step(t, inverted = false), 0.01f)
    }

    @Test
    fun sustainedReverseTurn_curvesSmoothly_respectsInvert_andDecaysWhenStraight() {
        val estimator = MotionSteeringEstimator()
        var t = 4000L
        var peakNormal = 0f
        for (i in 0..25) {
            estimator.onVideoMotionScore(7.5f, t)
            // Negative yaw around +gravity up axis -> positive right curvature before invert
            estimator.onGyroSample(0f, -0.24f, 0f, 0f, 9.81f, 0f, true, t)
            val deg = estimator.step(t, inverted = false)
            if (abs(deg) > abs(peakNormal)) peakNormal = deg
            t += 33L
        }
        assertTrue("Expected noticeable reverse curve (>= 15 deg), got $peakNormal", peakNormal >= 15f)
        assertTrue("Expected clamped within 35 deg, got $peakNormal", peakNormal <= 35f)

        val invertedDeg = estimator.step(t, inverted = true)
        assertTrue("Invert switch must flip steering direction", invertedDeg < 0f)

        // Straighten wheel: yaw returns to 0 and settles smoothly back to center
        for (i in 0..30) {
            estimator.onGyroSample(0f, 0f, 0f, 0f, 9.81f, 0f, true, t)
            estimator.step(t, inverted = false)
            t += 33L
        }
        assertEquals("Guidelines must return smoothly to straight center", 0f, estimator.step(t, inverted = false), 0.5f)
    }

    @Test
    fun steeringResolver_prioritizesVerifiedAngle_andIgnoresZeroBroadcastReset() {
        val resolver = GuideSteeringResolver()
        // Zero legacy broadcast must not suppress motion fallback
        resolver.setLegacySteeringDegrees(0f, inverted = false)
        assertEquals(14f, resolver.resolveTargetDegrees(motionDegrees = 14f), 0.01f)

        // Explicit non-zero broadcast works
        resolver.setLegacySteeringDegrees(225f, inverted = false)
        assertEquals(15f, resolver.resolveTargetDegrees(motionDegrees = 5f), 0.01f)

        // Verified road-wheel angle strictly wins over both
        resolver.setVerifiedRoadWheelAngleDegrees(-28f)
        assertEquals(-28f, resolver.resolveTargetDegrees(motionDegrees = 14f), 0.01f)
    }
}

package ai.tigeriq.camera

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.nio.ByteBuffer

class UvcMotionEvidenceTest {

    @Test
    fun computeRoadMotionScore_rejectsExposureShift_andDetectsTextureMotion() {
        val width = 64
        val height = 48
        val prev = ByteArray(UvcFrameSignalEvidence.ROAD_MOTION_GRID_SIZE)
        val curr = ByteArray(UvcFrameSignalEvidence.ROAD_MOTION_GRID_SIZE)

        val baseFrame = ByteArray(width * height + (width * height) / 2)
        for (y in 0 until height) {
            for (x in 0 until width) {
                baseFrame[y * width + x] = ((x * 5 + y * 3) % 160 + 20).toByte()
            }
        }

        val firstScore = UvcFrameSignalEvidence.computeRoadMotionScore(
            ByteBuffer.wrap(baseFrame), width, height, prev, curr
        )
        assertNotNull(firstScore)
        System.arraycopy(curr, 0, prev, 0, curr.size)

        // Identical frame -> ~0 motion
        val staticScore = UvcFrameSignalEvidence.computeRoadMotionScore(
            ByteBuffer.wrap(baseFrame), width, height, prev, curr
        )!!
        assertEquals(0f, staticScore, 0.01f)

        // Uniform auto-exposure brightness jump (+35 everywhere) -> still near 0 motion
        val brighterFrame = baseFrame.copyOf()
        for (i in 0 until width * height) {
            brighterFrame[i] = ((brighterFrame[i].toInt() and 0xFF) + 35).coerceAtMost(255).toByte()
        }
        val agcScore = UvcFrameSignalEvidence.computeRoadMotionScore(
            ByteBuffer.wrap(brighterFrame), width, height, prev, curr
        )!!
        assertTrue("Exposure jump must not register as movement: $agcScore", agcScore < 1.0f)

        // Shift horizontal pavement texture -> detects movement clearly
        val shiftedFrame = ByteArray(baseFrame.size)
        for (y in 0 until height) {
            for (x in 0 until width) {
                val sx = (x + 12) % width
                shiftedFrame[y * width + x] = ((sx * 5 + y * 3) % 160 + 20).toByte()
            }
        }
        val motionScore = UvcFrameSignalEvidence.computeRoadMotionScore(
            ByteBuffer.wrap(shiftedFrame), width, height, prev, curr
        )!!
        assertTrue("Expected noticeable road texture shift score >= 5f, got $motionScore", motionScore >= 5f)
    }

    @Test
    fun computeRoadMotionScore_handlesUndersizedBufferSafely() {
        val prev = ByteArray(32)
        val curr = ByteArray(32)
        val tiny = ByteBuffer.allocate(100)
        assertNull(UvcFrameSignalEvidence.computeRoadMotionScore(tiny, 64, 48, prev, curr))
    }
}

