            gravityX = v[0]
            gravityY = v[1]
            gravityZ = v[2]
            gravityReady = true
        }
        Sensor.TYPE_GYROSCOPE -> {
            motionEstimator.onGyroSample(
                wx = v[0], wy = v[1], wz = v[2],
                gx = gravityX, gy = gravityY, gz = gravityZ,
                hasGravity = gravityReady,
                timestampMs = SystemClock.uptimeMillis()
            )
        }
    }
}

